{
  "name": "@kimaki/automode",
  "version": "1.0.1",
  "type": "module",
  "description": "OpenCode plugin that gates tool execution with a two-stage LLM classifier, like Claude Code auto mode.",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    "./package.json": "./package.json",
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./src": {
      "types": "./src/index.ts",
      "default": "./src/index.ts"
    },
    "./src/*": {
      "types": "./src/*.ts",
      "default": "./src/*.ts"
    }
  },
  "files": [
    "src",
    "dist"
  ],
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "opencode",
    "plugin",
    "auto-mode",
    "permissions",
    "guardrails"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/remorses/kimaki",
    "directory": "opencode-auto-mode"
  },
  "homepage": "https://github.com/remorses/kimaki",
  "bugs": "https://github.com/remorses/kimaki/issues",
  "license": "MIT",
  "engines": {
    "node": ">=22"
  },
  "dependencies": {
    "@ai-sdk/gateway": "4.0.85",
    "ai": "7.0.105",
    "unbash": "^4.0.11"
  },
  "devDependencies": {
    "@opencode/client": "2.0.29",
    "@opencode/plugin": "2.0.29",
    "@types/node": "^24.3.0",
    "rimraf": "^6.0.1",
    "string-dedent": "^3.0.2",
    "opencode-deterministic-provider": "^0.0.1"
  },
  "peerDependencies": {
    "@opencode/client": "2.0.29",
    "@opencode/plugin": "2.0.29"
  },
  "scripts": {
    "build": "tsc",
    "test": "vitest --run",
    "typecheck": "tsc"
  }
}
